"""Local, authored continuous-build demonstration. No project operations."""
from studio_examples import image_data

SCENES = [
 ('Plan','An idea finds its structure.','A sentence becomes a shared plan.','Audience: art directors. Structure: work, biography, enquiry. Interaction: filter Interiors. Real generation requires brief approval.'),
 ('Generate','Watch the page take shape.','Structure. Identity. A website.','The brief and wireframe share a grid. Type, photographs and captions settle into their actual places. Prebuilt content, not an AI request.'),
 ('Direction','Same idea. Another expression.','Try a visual direction without starting over.','Editorial, Studio grid or Quiet minimal: each changes composition, typography, spacing and palette. Scrolling never changes your selection.'),
 ('Test','A click should mean something.','Action: select Interiors. Expected: only interior photographs.','Simulated demonstration · Missing listener. Expected 1, observed 2. Real behavior tests require approval.'),
 ('Repair','Follow the failure to its source.','One handler. One visible consequence.','Simulated demonstration · Example attempt 1 of 3 maximum. Connect the listener to the gallery. Preserve the original and inspect the difference.'),
 ('Retest','The same action. New evidence.','Repeat the check that exposed the problem.','Simulated demonstration · Same check: select Interiors. Expected 1 photograph. Illustrated repaired outcome: 1 photograph. Other behavior is untested.'),
 ('Review','See what changed. Decide what stays.','A version, its difference, and the behavior checked.','Simulated demonstration · Compare original and repaired views. Passing a check confirms only the behavior tested. You decide what to keep.'),
 ('Begin','What will you make next?','Start with an idea. Shape it into something you can explore.','This sample ends here. Start your project below. Approve the editable brief before generation.'),
]

def render_story():
    architecture,landscape=image_data('architecture.jpg'),image_data('landscape.jpg')
    def still(i):
        if i==0:return '<div class="story-still">IDEA → BRIEF<br><b>A quieter way of seeing.</b><br>Audience · Structure · Direction · Filter<br>Approval required before real generation</div>'
        if i==4:return '<pre class="story-still">SIMULATED REPAIR / 1 OF 3 MAX\n− // no listener\n+ button.addEventListener(\n+   "click", filterGallery);</pre>'
        return f'<figure class="story-still"><small>{SCENES[i][0].upper()} / SAMPLE PROJECT</small><img src="{architecture}" alt="Architectural photograph in the sample portfolio"><figcaption>Interiors / Studies in form</figcaption></figure>'
    narrative=''.join(f'<section class="story-copy" data-scene="{i}"><small>0{i+1} / {name.upper()}</small><h3>{title}</h3><p>{description}</p><p class="story-detail">{evidence}</p>{still(i)}</section>' for i,(name,title,description,evidence) in enumerate(SCENES))
    transcript=''.join(f'<section><h3>{name}: {title}</h3><p>{description}</p><p>{evidence}</p></section>' for name,title,description,evidence in SCENES)
    track=''.join(f'<span data-stage="{i}">{name}</span>' for i,name in enumerate(['Plan','Generate','Test','Repair','Retest','Review']))
    return f'''<section id="how-it-works" class="canvas-story" data-story-style="editorial">
<header class="story-prologue"><p class="studio-kicker">THE CONTINUOUS BUILD / 02</p><h2>One idea.<br><em>Many possibilities.</em></h2><p>Interactive demonstration · Sample project</p><p class="story-detail">Mira Lane / Architectural photographer. A fixed sample; your playground choice above stays yours.</p><button type="button" data-story-motion aria-pressed="false">Read without animation</button><a href="#begin-project">Skip to your project ↗</a></header>
<div class="story-runway"><div class="story-pin"><div class="story-track" aria-label="Sample workflow"><b class="story-project">[↗ MIRA LANE</b>{track}<i class="track-marker" aria-hidden="true"></i></div>
<div class="story-composition"><div class="story-narration" aria-hidden="true">{narrative}</div><div class="story-stack"><div class="story-layer layer-brief" aria-hidden="true">BRIEF / Work · About · Enquiry</div><div class="story-layer layer-code" aria-hidden="true">index.html / filterGallery()</div>
<div class="becoming-canvas"><div class="story-chrome"><b>[↗ <span class="canvas-project-label">MIRA LANE</span></b><span>Sample / index.html</span><span class="assembly-phase">Idea → Brief</span></div>
<div class="morph-page" aria-hidden="true"><div class="construction-grid"></div><i class="blue-focus"></i><div class="morph-title"><small>SELECTED WORK / 2026</small><h3>A quieter way<br>of seeing.</h3><p class="idea-thread">A portfolio for an architectural photographer.</p></div>
<div class="brief-lines"><div data-field="0">AUDIENCE <b>Art directors &amp; photography clients</b></div><div data-field="1">STRUCTURE <b>Work · About · Enquiry</b></div><div data-field="2">DIRECTION <b>Editorial / spacious / photographs first</b></div><div data-field="3">INTERACTION <b>Filter photographs by category</b></div><small>APPROVAL REQUIRED / REAL PROJECTS</small></div>
<div class="morph-gallery"><div class="story-filters"><span>All</span><span class="filter-target">Interiors</span></div><div class="story-images"><figure class="landscape-photo"><img src="{landscape}" alt=""><figcaption>01 / Coastal light · Landscapes</figcaption></figure><figure class="interiors-photo"><img src="{architecture}" alt=""><figcaption>02 / Studies in form · Interiors</figcaption></figure></div><p class="sample-gallery-count">Selected work / 2 photographs</p></div><div class="sample-footer"><span>MIRA LANE / PHOTOGRAPHY</span><span>Work with me ↗</span></div>
<div class="wireframe-labels"><span>01 / HEADER</span><span>02 / HERO</span><span>03 / GALLERY</span><span>04 / FOOTER</span></div><div class="demo-cursor"><svg viewBox="0 0 24 28" width="24" height="28"><path d="M2 2v22l6-6 5 8 4-2-5-8h9Z" fill="#6B8AFF" stroke="#101114" stroke-width="2"/></svg><small>DEMO POINTER</small></div>
<div class="inspection-evidence"><small>SIMULATED DEMONSTRATION</small><b>Check: select Interiors → one photograph</b><span class="failure-evidence">× Example failure · expected 1, observed 2</span><span class="retest-evidence">✓ Same check · illustrated outcome: 1 photograph</span></div>
<div class="repair-difference"><small>SIMULATED DEMONSTRATION / ATTEMPT 1 OF 3 MAX</small><div class="comparison-labels"><b>Original / 2 visible</b><b>Repaired / 1 visible</b></div><div class="comparison-views"><div><img src="{landscape}" alt=""><img src="{architecture}" alt=""></div><div><img src="{architecture}" alt=""></div><i class="comparison-divider"></i></div><pre><del>− // filter has no click listener</del>\n<ins>+ button.addEventListener('click', () =&gt; {{\n+   card.hidden = selected !== 'All' &amp;&amp;\n+     card.dataset.category !== selected;\n+ }});</ins></pre><span class="code-connector">HANDLER ↔ INTERIORS FILTER</span></div>
<div class="review-strip">SAMPLE REVIEW / Version 2 · Handler difference · One illustrated check</div></div></div>
<div class="style-orbit" aria-label="Sample visual directions"><button type="button" data-story-choice="editorial" aria-pressed="true"><span class="mini-editorial"><i>A quieter<br><em>way.</em></i><b></b></span>Editorial</button><button type="button" data-story-choice="grid" aria-pressed="false"><span class="mini-grid"><i>MAKE<br>SPACE.</i><b></b></span>Studio grid</button><button type="button" data-story-choice="minimal" aria-pressed="false"><span class="mini-minimal"><i>Less, considered.</i><b></b></span>Quiet minimal</button><i class="style-traveller" aria-hidden="true"></i></div>
</div></div><div class="story-transport"><button type="button" data-story-replay>▶ Replay demonstration</button><span class="replay-description">Local sample only · no AI call</span><label class="review-control">Compare original / repaired<input type="range" data-story-divider min="0" max="100" value="50" aria-label="Original and repaired comparison divider"></label><span class="replay-status" role="status"></span></div></div></div>
<details class="story-transcript"><summary>Read the complete walkthrough</summary>{transcript}</details><div id="begin-project" class="story-ending"><p class="studio-kicker">YOUR TURN / 03</p><h2><span>What will you</span><br><em>make next?</em></h2><p>Start with an idea. Shape it into something you can explore.</p><p class="story-detail">The sample is a demonstration. Your brief, tests and changes remain your decisions.</p></div></section>'''
